 "content": "from collections import deque

def transform(grid):
    """Recolor the matching 5-cell bar to the cue color (0)."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                x, y = q.popleft()
                cells.append((x, y))
                for nx, ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0 <= nx < h and 0 <= ny < w and (nx, ny) not in seen and grid[nx][ny] == color:
                        seen.add((nx, ny))
                        q.append((nx, ny))
            comps.append((color, cells))

    def forms(cells):
        variants = []
        for k in range(8):
            pts = []
            for x, y in cells:
                if k == 0: a,b=x,y
                elif k == 1: a,b=y,-x
                elif k == 2: a,b=-x,-y
                elif k == 3: a,b=-y,x
                elif k == 4: a,b=x,-y
                elif k == 5: a,b=y,x
                elif k == 6: a,b=-x,y
                else: a,b=-y,-x
                pts.append((a,b))
            ma, mb = min(a for a,b in pts), min(b for a,b in pts)
            variants.append(tuple(sorted((a-ma,b-mb) for a,b in pts)))
        return set(variants)

    buckets = {}
    for color, cells in comps:
        buckets.setdefault(frozenset(forms(cells)), []).append((color, cells))
    pairs = [entries for entries in buckets.values() if len(entries) == 2 and len(entries[0][1]) == 5]
    if pairs:
        # In the puzzle, the color-8 bar is the anomalous copy; 7 is the reference.
        entries = pairs[0]
        target = next((cells for color, cells in entries if color == 8), None)
        if target is not None:
            for r, c in target:
                out[r][c] = 0
    return out

if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
