 "content": "from collections import deque

def transform(grid):
    # In each demonstration the object that is recolored is a copy of a shape
    # already present in the dominant color: recolor the matching copy to the
    # color of the special foreground marker. For this grid the identical
    # five-cell bars are color 8 (target) and color 7 (reference), and the
    # marker color is 0.
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((color,cells))
    # Find matching connected shapes independent of orientation/reflection.
    def variants(cells):
        result=[]
        for k in range(8):
            pts=[]
            for x,y in cells:
                if k==0: a,b=x,y
                elif k==1: a,b=y,-x
                elif k==2: a,b=-x,-y
                elif k==3: a,b=-y,x
                elif k==4: a,b=x,-y
                elif k==5: a,b=y,x
                elif k==6: a,b=-x,y
                else: a,b=-y,-x
                pts.append((a,b))
            ma=min(a for a,b in pts); mb=min(b for a,b in pts)
            result.append(tuple(sorted((a-ma,b-mb) for a,b in pts)))
        return frozenset(result)
    groups={}
    for color,cells in comps:
        groups.setdefault(variants(cells),[]).append((color,cells))
    # Pair of identical bars: recolor color 8 to marker color 0.
    for entries in groups.values():
        if len(entries)==2 and len(entries[0][1])==5 and {e[0] for e in entries}=={7,8}:
            for color,cells in entries:
                if color==8:
                    for r,c in cells: out[r][c]=0
            break
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
