def canon(cells):
 vs=[]
 for k in range(8):
  pts=[]
  for x,y in cells:
   f=[(x,y),(y,-x),(-x,-y),(-y,x),(x,-y),(y,x),(-x,y),(-y,-x)][k];pts.append(f)
  a=min(x for x,y in pts);b=min(y for x,y in pts);vs.append(tuple(sorted((x-a,y-b) for x,y in pts)))
 return min(vs)
