p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-rnd0/frozen/seen/play/users/u059/system/state/hermes/state.db'; c=sqlite3.connect('file:'+p+'?mode=ro',uri=True); sid='50241e3b-e0a5-42e4-899d-9606ca9c859d'; msgs=c.execute("select id,content from messages where session_id=? and role='user' order by id",(sid,)).fetchall()
def getg(t,pat):
 m=re.search(pat,t); rows=[]; started=False
 if not m:return
 for line in t[m.end():].splitlines():
  if not line.strip():
   if started: break
   continue
  if not re.fullmatch(r'\d+(?:\s+\d+)*',line.strip()):break
  started=True;rows.append(list(map(int,line.split())))
 return rows
def comps(g,bg):
 h,w=len(g),len(g[0]); seen=set(); out=[]
 for r in range(h):
  for col in range(w):
   v=g[r][col]
   if v==bg or (r,col) in seen:continue
   q=[(r,col)];seen.add((r,col)); pts=[]
   while q:
    x,y=q.pop();pts.append((x,y))
    for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==v:seen.add((nx,ny));q.append((nx,ny))
   out.append((v,pts))
 return out
for mid,t in msgs:
 if not t:continue
 m=re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):',t)
 if not m:continue
 n=m.group(1); a=getg(t,rf'Demo pair {n} input \(\d+x\d+\):'); b=getg(t,rf'Demo pair {n} output \(\d+x\d+\):')
 if not a or not b:continue
 dif=[(r,c,a[r][c],b[r][c]) for r in range(len(a)) for c in range(len(a[0])) if a[r][c]!=b[r][c]]; target={(r,c) for r,c,_,_ in dif}; src=dif[0][2]; dst=dif[0][3]
 print('\nD',n,'target',src,'->',dst,sorted(target))
 for col,pts in comps(a,collections.Counter(x for row in a for x in row).most_common(1)[0][0]):
  if col==src and set(pts)==target: mark='TARGET'
  else:mark=''
  if col in (src,dst) or mark:print(col,len(pts),(min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts)),mark)
 # target distance nearest dst component and component distances
 for col,pts in comps(a,collections.Counter(x for row in a for x in row).most_common(1)[0][0]):
  if col==src and set(pts)==target:continue
 # neighbors adjacent around target and any exact-contact
 nbr=collections.Counter(a[nr][nc] for r,c in target for nr,nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)) if 0<=nr<len(a) and 0<=nc<len(a[0]) and (nr,nc) not in target)
 print('target boundary colors',nbr)

