p='/home/USER/continual-arc-baselines/.workbench/stage1/HPL0-hermes-luna6-medium-rnd0/frozen/seen/play/users/u059/system/state/hermes/state.db'; c=sqlite3.connect('file:'+p+'?mode=ro',uri=True); sid='50241e3b-e0a5-42e4-899d-9606ca9c859d'
t=c.execute("select content from messages where id=1063").fetchone()[0]
m=re.search(r'Test input \((\d+)x(\d+)\):',t); rows=[]; started=False
for line in t[m.end():].splitlines():
 if not line.strip():
  if started:break
  continue
 if not re.fullmatch(r'\d+(?:\s+\d+)*',line.strip()):break
 started=True; rows.append(list(map(int,line.split())))
g=rows; h=len(g);w=len(g[0]);bg=9; seen=set(); cs=[]
for r in range(h):
 for col in range(w):
  v=g[r][col]
  if v==bg or (r,col) in seen:continue
  q=[(r,col)];seen.add((r,col));pts=[]
  while q:
   x,y=q.pop();pts.append((x,y))
   for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and g[nx][ny]==v:seen.add((nx,ny));q.append((nx,ny))
  cs.append((v,pts))
print('shape',h,w,'color counts',collections.Counter(x for row in g for x in row))
for i,(v,pts) in enumerate(cs): print(i,'color',v,'area',len(pts),'bbox',(min(x for x,y in pts),max(x for x,y in pts),min(y for x,y in pts),max(y for x,y in pts)),'coords',sorted(pts))

