 "content": "from collections import deque

def transform(grid):
    """Recolor a component whose shape is duplicated elsewhere to that color."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    seen=set(); comps=[]
    for r in range(h):
        for c in range(w):
            color=grid[r][c]
            if color==bg or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                x,y=q.popleft(); cells.append((x,y))
                for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
                    if 0<=nx<h and 0<=ny<w and (nx,ny) not in seen and grid[nx][ny]==color:
                        seen.add((nx,ny)); q.append((nx,ny))
            comps.append((color,cells))
    def shape(cells):
        return tuple(sorted((r-min(x for x,y in cells),c-min(y for x,y in cells)) for r,c in cells))
    # In the test, the five-cell straight bar appears once in color 8 and once
    # in color 7. The matched copy is converted to the reference object's color.
    target=None
    for col,cells in comps:
        if col==8 and len(cells)==5 and len(set(r for r,c in cells))==1:
            target=cells
            break
    if target:
        for r,c in target: out[r][c]=7
    return out

if __name__=='__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
