 for label in ('input','output'):
  m=re.search(rf'Demo pair [46] {label} \(\d+x\d+\):\n((?:[0-9 ]+\n)+)',s)
  rows=[list(map(int,x.split())) for x in m.group(1).strip().splitlines()]
  h,w=len(rows),len(rows[0]); counts=collections.Counter(v for row in rows for v in row)
  print(label,'counts',counts)
  if label=='input':
   # connected components of non-bg (most frequent color)
   bg=counts.most_common(1)[0][0]; seen=set(); comps=[]
   for r in range(h):
    for col in range(w):
     color=rows[r][col]
     if color==bg or (r,col) in seen: continue
     stack=[(r,col)];seen.add((r,col));cells=[]
     while stack:
      y,x=stack.pop();cells.append((y,x))
      for q in ((y+1,x),(y-1,x),(y,x+1),(y,x-1)):
       yy,xx=q
       if 0<=yy<h and 0<=xx<w and q not in seen and rows[yy][xx]==color:
        seen.add(q);stack.append(q)
     comps.append((color,len(cells),(min(y for y,x in cells),min(x for y,x in cells),max(y for y,x in cells),max(x for y,x in cells)),cells))
   for q in comps: print(' comp',q[:3],q[3])
