def comps(g):
 h,w=len(g),len(g[0]); seen=set(); ret=[]
 for r in range(h):
  for col in range(w):
   color=g[r][col]
   if color==max(collections.Counter(x for row in g for x in row),key=collections.Counter(x for row in g for x in row).get) or (r,col) in seen: continue
   st=[(r,col)];seen.add((r,col)); cells=[]
